    add(*extra)
    vt=pe.va2f(VT); need([pe.va2f(S.unpack_from('<Q',pe.raw,vt+8*d)[0]) for d in (2,19,20)]==[0x1041f30,ENTRY,0x1041130],'NATION vslots')
